import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, arrival, active)
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    arrival_counter = 0

    def clean_buy():
        while buy_heap:
            neg_price, arrival, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell():
        while sell_heap:
            price, arrival, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        arrival_counter += 1
        arrival = arrival_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = qty
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = qty
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
            remaining = qty
        else:
            continue

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                s_price, s_arrival, s_id = sell_heap[0]
                if typ != 'market' and price < s_price:
                    break
                s_info = book[s_id]
                trade_qty = min(remaining, s_info['qty'])
                trades.append([oid, s_id, s_price, trade_qty])
                remaining -= trade_qty
                s_info['qty'] -= trade_qty
                if s_info['qty'] <= 0:
                    s_info['active'] = False
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                info = {'side': 'buy', 'price': price, 'qty': remaining, 'arrival': arrival, 'active': True}
                book[oid] = info
                heapq.heappush(buy_heap, (-price, arrival, oid))
            elif typ == 'limit' and remaining == 0:
                pass
            else:
                pass
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                neg_price, b_arrival, b_id = buy_heap[0]
                b_price = -neg_price
                if typ != 'market' and price > b_price:
                    break
                b_info = book[b_id]
                trade_qty = min(remaining, b_info['qty'])
                trades.append([b_id, oid, b_price, trade_qty])
                remaining -= trade_qty
                b_info['qty'] -= trade_qty
                if b_info['qty'] <= 0:
                    b_info['active'] = False
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                info = {'side': 'sell', 'price': price, 'qty': remaining, 'arrival': arrival, 'active': True}
                book[oid] = info
                heapq.heappush(sell_heap, (price, arrival, oid))

        if typ in ('limit',) and remaining > 0:
            # already handled above for both sides, but keep book entry qty consistent
            pass
        elif typ == 'limit' and remaining == 0:
            # fully filled, ensure not left in book (it never was added)
            pass

    return trades

